export const tokens = T
const { ui: C, space: S, type: Y } = T
export const palette = T.map

// inter's optical size for a font size, as measured off the drawings (they
// were made at 2x, so it runs near twice the size), set wherever size is
export const opsz = size => `font-variation-settings:"opsz" ${
  Y.opsz[parseFloat(size)] ?? 32}`
// greyscale antialiasing, as figma draws white on black, and the weights as
// drawn (regular 370, bold 750: inferred, ir/tokens.json type.ui)
const FONT = `font:${Y.regular} ${Y.text}/${Y.leading} ${Y.family};`
  + `font-feature-settings:${Y.features.map(f => `"${f}"`)};${opsz(Y.text)};`
  + '-webkit-font-smoothing:antialiased;-moz-osx-font-smoothing:grayscale'
const sheet = css => {
  const s = new CSSStyleSheet()
  s.replaceSync(css)
  return s
}
// every element: the ui type, set on the element itself so nothing a page
// sets on the host is inherited past it
const BASE = sheet(`:host{display:block}:host([hidden]){display:none}
*{box-sizing:border-box;margin:0;padding:0}
.ui{${FONT};color:${C.text};text-align:left;letter-spacing:normal;
text-transform:none;font-style:normal}
button{all:unset;box-sizing:border-box;cursor:pointer}
button:focus-visible{outline:1px solid ${C.text};outline-offset:2px}`)
// tokens on :root, read-only by convention, for what a page draws itself:
// --dd-ui-border, --dd-map-red, --dd-gap-s, --dd-weight …
const vars = (o, p) => Object.entries(o).map(([k, v]) =>
  `--dd-${p}${k.replace(/[A-Z]/g, c => '-' + c.toLowerCase())}:${v}`)
document.adoptedStyleSheets = [...document.adoptedStyleSheets, sheet(
  `:root{${[...vars(C, 'ui-'), ...vars(T.map, 'map-'), ...vars(S, ''),
    ...vars({ weight: Y.regular, weightBold: Y.bold }, '')].join(';')}}`)]

// a custom element from its css and markup; `init` wires it once
const define = (name, css, html, init, attrs = []) =>
  customElements.get(name) || customElements.define(name,
    class extends HTMLElement {
      static observedAttributes = attrs
      constructor() {
        super()
        const r = this.attachShadow({ mode: 'open' })
        r.adoptedStyleSheets = [BASE, sheet(css)]
        r.innerHTML = html(this)
        init?.(this, r)
      }
      attributeChangedCallback() { this.render?.() }
    })

const CHEVRON = '<svg viewBox="0 0 8 4" width="8" height="4"><path '
  + 'd="M.5 3.5 4 .5l3.5 3" fill="none" stroke="currentColor"/></svg>'
const INFO = '<svg viewBox="0 0 10 10" width="10" height="10" fill="none" '
  + 'stroke="currentColor"><circle cx="5" cy="5" r="4.5"/><path d="M5 4.2v3.3'
  + '"/><circle cx="5" cy="2.7" r=".2" stroke-width=".9"/></svg>'
// the chevron hangs in the left padding, pairGap off the content edge; its
// button is a finger wide, the drawn chevron 8×4 inside it
const HANG = `.chev{position:absolute;width:20px;height:16px;display:none;
left:calc(-${S.pairGap} - 14px);color:${C.border};place-items:center}
.chev svg{display:block}`
const esc = s => String(s ?? '').replace(/[&<>"]/g,
  c => `&#${c.charCodeAt(0)};`)
const fire = (el, type) => el.dispatchEvent(new Event(type,
  { bubbles: true, composed: true }))

// ── holding device (pdf:79, 83-86) ──
// <dd-panel pad=l|s gap=l|s collapsible collapsed info intro>
//   <span slot=title>…</span><span slot=subtitle>…</span> content
// </dd-panel>. a collapsible panel keeps the l left padding the chevron
// hangs in; contracting hides the content in place (ruling 2026-07-08).
// a heading is one line: a long one ends in an ellipsis, the text whole
// underneath, so a triple click selects and copies all of it
define('dd-panel', `:host{display:flex;flex-direction:column;min-height:0}
.box{flex:1 1 auto;min-height:0;overflow:auto;background:${C.background};
border:1px solid ${C.border};padding:${S.paddingL};display:flex;
flex-direction:column;gap:${S.gapL};scrollbar-width:thin;
scrollbar-color:${C.inactive} transparent}
.body{display:flex;flex-direction:column;gap:${S.gapL}}
:host([pad=s]) .box{padding:${S.paddingS}}
:host([collapsible]) .box{padding-left:${S.paddingL}}
:host([gap=s]) :is(.box,.body){gap:${S.gapS}}
:host([collapsed]) .body{display:none}
.head{position:relative}.head[hidden],.sub[hidden]{display:none}
.title{display:flex;align-items:center;gap:${S.buttonPadX};
border-bottom:1px solid ${C.border};padding-bottom:${S.headRule}}
.title slot{display:block;flex:1;min-width:0;overflow:hidden;
white-space:nowrap;text-overflow:ellipsis}
:host([collapsible]) .title slot{cursor:pointer}
.info{display:none;flex:none;width:10px;height:10px}
.info svg{display:block}:host([info]) .info{display:block}
.sub{margin-top:${S.subtitleGap}}
${HANG}.chev{top:calc(${S.chevronTop} - 6px)}
:host([collapsible]) .chev{display:grid}
:host([collapsed]) .chev svg{transform:rotate(180deg)}
:host([intro]) .box{font-size:${Y.introBody};${opsz(Y.introBody)};
gap:${S.gapS}}
:host([intro]) .title{font-size:${Y.introHeading};${opsz(Y.introHeading)};
font-weight:${Y.bold};
letter-spacing:${Y.tracking};line-height:${Y.leading};border:0;
padding:0}`,
() => `<div class="ui box"><div class="head"><button class="chev"
aria-label="Contract">${CHEVRON}</button><div class="title"><slot
name="title"></slot><button class="info" aria-label="About">${INFO}
</button></div><div class="sub"><slot name="subtitle"></slot></div></div>
<div class="body"><slot></slot></div></div>`,
(el, r) => {
  const $ = s => r.querySelector(s)
  const show = () => {
    const has = n => $(`slot[name=${n}]`).assignedNodes()
      .some(x => x.textContent.trim() || x.nodeType === 1)
    $('.head').hidden = !has('title')
    $('.sub').hidden = !has('subtitle')
  }
  r.addEventListener('slotchange', show)
  show()
  const toggle = () => {
    if (!el.hasAttribute('collapsible')) return
    el.toggleAttribute('collapsed')
    fire(el, 'toggle')
  }
  $('.chev').onclick = toggle
  // a heading click toggles once it is plainly not the start of a double or
  // triple click (which select), nor the end of a drag that selected
  let wait
  $('slot[name=title]').onclick = e => {
    clearTimeout(wait)
    if (e.target.closest('a') || e.detail > 1) return
    wait = setTimeout(() => getSelection().isCollapsed && toggle(), 300)
  }
  $('.info').onclick = () => fire(el, 'info')
})

// ── interactive elements (pdf:80-82) ──
const BOX = `.b{display:block;width:100%;text-align:center;
padding:${S.controlPadY} ${S.buttonPadX};border:solid ${C.border};
border-width:0 1px}.b:hover{background:${C.hover}}
:host([disabled]) .b{color:${C.inactive};pointer-events:none}`
define('dd-btn', BOX, () => '<button class="ui b"><slot></slot></button>')
// buttons 2 × 1: equal widths, pairGap apart
define('dd-btns', `.p{display:flex;gap:${S.pairGap}}
::slotted(*){flex:1;min-width:0}`, () => '<div class="p"><slot></slot></div>')

// <dd-row selectable active> label, data… — the label left, the data in
// columns to its right, each set from its left edge as drawn (pdf:89), at
// widths a page sets with --dd-cols (layout is the page's). a plain row is
// a statistic; a selectable one has the l&r borders and inverts when active
define('dd-row', `.r{display:grid;align-items:baseline;
grid-template-columns:var(--dd-cols,1fr auto);column-gap:${S.rowColumnGap}}
:host([inset]) .r{padding:0 ${S.buttonPadX}}
:host([selectable]) .r{padding:${S.rowPadY} ${S.buttonPadX};cursor:pointer;
border:solid ${C.border};border-width:0 1px}
:host([selectable]:hover) .r{background:${C.hover}}
:host([active]) .r,:host([active]:hover) .r{background:${C.activeBackground};
color:${C.activeText}}`, () => '<div class="ui r"><slot></slot></div>')

// <dd-toggle value=a><button value=a>A</button><button value=b>B</button>
// </dd-toggle>: options a divider and pairGap apart, inactive greyed
// the options are the page's nodes, and a page's own rules beat ::slotted
// ones (a reset's padding:0, button{color:inherit}): important, so they don't
define('dd-toggle', `.t{display:flex}
::slotted(*){all:unset!important;cursor:pointer!important;
color:${C.inactive}!important;padding:${S.controlPadY} 0!important}
::slotted(:not(:first-child)){border-left:1px solid ${C.border}!important;
padding-left:${S.pairGap}!important;margin-left:${S.pairGap}!important}
::slotted([aria-pressed=true]){color:${C.text}!important}`,
() => '<div class="ui t"><slot></slot></div>',
el => {
  el.render = () => {
    for (const o of el.querySelectorAll('[value]'))
      o.setAttribute('aria-pressed', o.getAttribute('value') === el.value)
  }
  el.addEventListener('click', e => {
    const o = e.target.closest('[value]')
    const v = o?.getAttribute('value')
    if (!o || o.parentElement !== el || v === el.value) return
    el.setAttribute('value', v)
    fire(el, 'change')
  })
  Object.defineProperty(el, 'value', { get: () => el.getAttribute('value') })
  queueMicrotask(el.render)
}, ['value'])

// <dd-dot active|unavailable>: unavailable 3×3 grey, inactive 3×3 white,
// active 8×8 white, each centred in a hit area a finger wide
define('dd-dot', `:host{display:inline-grid;place-items:center;
width:${S.dotHit};height:${S.dotHit};cursor:pointer;vertical-align:middle}
i{width:${S.dotInactive};height:${S.dotInactive};border-radius:50%;
background:${C.text}}
:host([active]) i{width:${S.dotActive};height:${S.dotActive}}
:host([unavailable]){pointer-events:none}
:host([unavailable]) i{background:${C.inactive}}`, () => '<i></i>',
el => {
  el.role = 'checkbox'
  el.tabIndex = 0
  el.render = () => { el.ariaChecked = el.hasAttribute('active') }
  el.addEventListener('keydown', e =>
    (e.key === ' ' || e.key === 'Enter') && (e.preventDefault(), el.click()))
}, ['active'])

// <dd-slider label min max step value>, .format(v) for the shown value
define('dd-slider', `.l{display:block;margin-bottom:${S.pairGap}}
.row{display:flex;align-items:center;gap:${S.sliderAmountGap}}
output{min-width:${S.sliderValue};text-align:right}
input{flex:1;min-width:0;appearance:none;background:none;height:${
  S.sliderThumb};margin:0;cursor:pointer}
input::-webkit-slider-runnable-track{height:1px;background:${C.text}}
input::-moz-range-track{height:1px;background:${C.text}}
input::-webkit-slider-thumb{appearance:none;width:${S.sliderThumb};
height:${S.sliderThumb};border-radius:50%;background:${C.text};
margin-top:calc(.5px - ${S.sliderThumb} / 2)}
input::-moz-range-thumb{width:${S.sliderThumb};height:${S.sliderThumb};
border:0;border-radius:50%;background:${C.text}}
input:focus-visible{outline:1px solid ${C.text};outline-offset:2px}`,
() => '<label class="ui"><span class="l"></span><span class="row"><input '
  + 'type="range"><output></output></span></label>',
(el, r) => {
  const input = r.querySelector('input'), out = r.querySelector('output')
  el.format = String
  el.render = () => {
    for (const a of ['min', 'max', 'step', 'value'])
      if (el.hasAttribute(a)) input.setAttribute(a, el.getAttribute(a))
    if (el.hasAttribute('value')) input.value = el.getAttribute('value')
    r.querySelector('.l').textContent = el.getAttribute('label') ?? ''
    out.textContent = el.format(+input.value)
  }
  input.oninput = () => { out.textContent = el.format(+input.value) }
  Object.defineProperty(el, 'value', { get: () => +input.value,
    set: v => { input.value = v; out.textContent = el.format(+v) } })
  el.render()
}, ['label', 'min', 'max', 'step', 'value'])

// ── the key (pdf:85) ──
// <dd-key row><dd-key-group label><dd-key-row mark color inactive>…
// one chevron, on the first group, and every group's label collapse the
// whole key; `row` lays the groups side by side, gap l (ruling 2026-07-08).
// open, it has more room under its last row than drawn (ruling 2026-10-09)
define('dd-key', `.box{background:${C.background};border:1px solid ${C.border};
padding:${S.keyPadY} ${S.paddingS} ${S.keyPadY} ${S.paddingL};display:flex;
flex-direction:column;gap:${S.gapS}}
:host([row]) .box{flex-direction:row;gap:${S.gapL}}
:host([collapsed]:not([row])) .box{gap:${S.keyLabelMarginBottom}}
:host(:not([collapsed])) .box{padding-bottom:${S.keyPadBottom}}`,
() => '<div class="ui box"><slot></slot></div>',
(el, r) => {
  const groups = () => [...el.children]
    .filter(g => g.localName === 'dd-key-group')
  el.render = () => groups().forEach((g, i) => {
    g.toggleAttribute('first', !i)
    g.toggleAttribute('collapsed', el.hasAttribute('collapsed'))
  })
  r.addEventListener('slotchange', el.render)
  el.addEventListener('dd-key-label', () => {
    el.toggleAttribute('collapsed')
    fire(el, 'toggle')
  })
}, ['collapsed'])

define('dd-key-group', `.label{position:relative;cursor:pointer;
white-space:pre}${HANG}.chev{top:calc((1lh - 16px) / 2)}
:host([first]) .chev{display:grid}
:host([collapsed]) .chev svg{transform:rotate(180deg)}
.rows{display:flex;flex-direction:column;gap:${S.keyRowGap};
margin-top:${S.keyLabelMarginBottom}}:host([collapsed]) .rows{display:none}`,
() => `<div class="ui"><div class="label"><button class="chev"
aria-label="Contract">${CHEVRON}</button><span></span></div><div
class="rows"><slot></slot></div></div>`,
(el, r) => {
  el.render = () => {
    r.querySelector('.label span').textContent = el.getAttribute('label')
  }
  r.querySelector('.label').onclick = () => fire(el, 'dd-key-label')
  el.render()
}, ['label'])

// a marking as inline svg, tinted; `scale` of its drawn size
export const markSVG = (name, color = C.text, scale = 1) =>
  T.marks[name].replace(/width="([\d.]+)" height="([\d.]+)"/, (_, w, h) =>
    `width="${w * scale}" height="${h * scale}"`)
    .replaceAll('currentColor', color)

// a row's marking sits at the top of a slot keyMark tall, the last row's
// slot only as tall as its marking, and the label centres on the marking
// (pdf:90)
define('dd-key-row', `.r{display:flex;align-items:flex-start;
gap:${S.paddingS};white-space:nowrap}.m{flex:none;width:${S.keyMark};
height:${S.keyMark};display:flex;justify-content:center}
:host(:last-child) .m{height:auto}.m svg{display:block}
.t{margin-top:calc((var(--h) - 1lh) / 2)}
:host([inactive]) .r{color:${C.inactive}}`,
() => '<div class="ui r"><span class="m"></span><span class="t"><slot>'
  + '</slot></span></div>',
(el, r) => {
  el.render = () => {
    const mark = el.getAttribute('mark'), m = r.querySelector('.m')
    m.innerHTML = mark in T.marks ? markSVG(mark,
      el.hasAttribute('inactive') ? C.inactive
        : el.getAttribute('color') || C.text, 0.8) : ''
    r.querySelector('.r').style.setProperty('--h',
      `${m.firstChild?.getAttribute('height') ?? 0}px`)
  }
  el.render()
}, ['mark', 'color', 'inactive'])

// ── on the map (pdf:72-74) ──
// <dd-label heading color>annotation</dd-label>: 11px, the title underlined,
// the annotation under it, in the colour of what it names
define('dd-label', `.l{white-space:nowrap;color:var(--c)}
.t{width:fit-content;border-bottom:1px solid;padding-bottom:1px}
.t:empty{display:none}`,
() => '<div class="ui l"><div class="t"></div><slot></slot></div>',
(el, r) => {
  el.render = () => {
    r.querySelector('.t').textContent = el.getAttribute('heading') ?? ''
    r.querySelector('.l').style.setProperty('--c',
      el.getAttribute('color') || C.text)
  }
  el.render()
}, ['heading', 'color'])

// the primary mark, 3.6667 × the ui text's cap height wide (pdf:6)
define('dd-logo', `:host{width:${S.logo};color:${C.text}}
a,svg{display:block;width:100%;height:auto;color:inherit}`,
el => `<a href="${esc(el.getAttribute('href') || 'https://datadesk.eco/')}"
target="_blank" rel="noopener" aria-label="Data Desk">${T.logo}</a>`)

// ── maplibre ──

// the dark basemap (pdf:64); a page that serves it elsewhere passes its url
export const style = new URL('./style.dark.json', import.meta.url).href

// a marking as a map image, `${name}-${color}`, for a symbol layer
export async function mark(map, name, color = C.text, scale = 2) {
  const id = `${name}-${color}`
  if (map.hasImage(id)) return id
  const img = new Image()
  const svg = markSVG(name, color, scale)
  img.src = 'data:image/svg+xml;base64,' + btoa(svg)
  await img.decode()
  if (!map.hasImage(id)) map.addImage(id, img, { pixelRatio: scale })
  return id
}
// every marking in every palette colour, as `${name}-${color}`, so a style
// can name any of them; anything else loads when maplibre asks for it
export const marks = map => {
  map.on('styleimagemissing', ({ id }) => {
    const [, name, color] = id.match(/^([a-z]+)-(#[0-9a-f]{6})$/i) ?? []
    if (name in T.marks) mark(map, name, color)
  })
  return Promise.all(Object.keys(T.marks).flatMap(n =>
    [...new Set(Object.values(T.map))].map(c => mark(map, n, c))))
}

// the satellite gradient map (pdf:62): luma in, a fixed lightness out at
// each stop, interpolated in L* between them. a lookup per grey level
const lstar = L => {
  const f = (L + 16) / 116, y = f > 6 / 29 ? f ** 3 : L / 903.3
  return 255 * (y > 0.0031308 ? 1.055 * y ** (1 / 2.4) - 0.055 : 12.92 * y)
}
export const ramp = ({ lightness: L, position: P } = T.grade) =>
  Uint8ClampedArray.from({ length: 256 }, (_, v) => {
    const t = v / 255, i = Math.max(1, P.findIndex(p => p >= t))
    const k = (t - P[i - 1]) / (P[i] - P[i - 1] || 1)
    return lstar(L[i - 1] + k * (L[i] - L[i - 1]))
  })
const LUT = ramp()
// an encoded tile in, the graded bitmap out, for a maplibre protocol
export async function grade(data, lut = LUT) {
  const bmp = await createImageBitmap(new Blob([data]))
  const c = new OffscreenCanvas(bmp.width, bmp.height)
  const x = c.getContext('2d')
  x.drawImage(bmp, 0, 0)
  const img = x.getImageData(0, 0, c.width, c.height), a = img.data
  for (let i = 0; i < a.length; i += 4)
    a[i] = a[i + 1] = a[i + 2] =
      lut[(a[i] * 54 + a[i + 1] * 183 + a[i + 2] * 19) >> 8]
  x.putImageData(img, 0, 0)
  return c.transferToImageBitmap()
}

// graded esri imagery fading in over the basemap where features resolve.
// esri's cache stops between z17 and z19 by place, and past it answers 200
// with a placeholder jpeg, so the placeholder is drawn as nothing and the
// source is stacked at the depths the cache stops at: the sharpest that
// resolved shows through. returns the layer ids. `gl` is maplibregl
const ESRI = 'ddsat://server.arcgisonline.com/ArcGIS/rest/services/'
  + 'World_Imagery/MapServer/tile/{z}/{y}/{x}'
const GAP = 2521   // the placeholder's length in bytes
export function imagery(map, { gl = globalThis.maplibregl, before,
  id = 'dd-imagery', fade = [7.5, 9] } = {}) {
  gl.addProtocol('ddsat', async ({ url }, { signal }) => {
    const res = await fetch(url.replace('ddsat:', 'https:'), { signal })
    const data = res.ok && await res.arrayBuffer()
    return { data: data && data.byteLength !== GAP ? await grade(data)
      : await createImageBitmap(new ImageData(1, 1)) }
  })
  return [[7, 17], [17, 18], [18, 19]].map(([minzoom, maxzoom], i) => {
    const l = i ? `${id}-${maxzoom}` : id
    map.addSource(l, { type: 'raster', tiles: [ESRI], tileSize: 256,
      maxzoom })
    map.addLayer({ id: l, type: 'raster', source: l, minzoom, paint: {
      'raster-opacity': ['interpolate', ['linear'], ['zoom'],
        ...fade.flatMap((z, i) => [z, i])] } }, before)
    return l
  })
}

// line, area and region styles (pdf:67-68): stroke style is the type,
// colour tells instances apart. spread into map.addLayer
const W = 1.5
export const lines = {
  pipeline: (c = C.text) => ({ type: 'line',
    paint: { 'line-color': c, 'line-width': W } }),
  uncertain: (c = C.text) => ({ type: 'line', paint: { 'line-color': c,
    'line-width': W, 'line-dasharray': [0.7, 0.7] } }),
  trail: (c = C.border) => ({ type: 'line', paint: { 'line-color': c,
    'line-width': 1, 'line-dasharray': [6, 4] } }),
  area: (c = C.text) => ({ type: 'line', paint: { 'line-color': c,
    'line-width': 1 } }),
  areaInset: (c = C.text) => ({ type: 'line', paint: { 'line-color': c,
    'line-width': 1, 'line-offset': 4, 'line-dasharray': [5, 4] } }),
}

// a label on the map, up and right of the marking it names (pdf:73)
export function label(map, lngLat, { heading, text = '', color, size = 15,
  gl = globalThis.maplibregl } = {}) {
  const el = document.createElement('dd-label')
  if (heading) el.setAttribute('heading', heading)
  if (color) el.setAttribute('color', color)
  el.innerHTML = String(text).split('\n').map(esc).join('<br>')
  return new gl.Marker({ element: el, anchor: 'bottom-left',
    offset: [size / 2 + 8, -size / 2] }).setLngLat(lngLat).addTo(map)
}

// a label on the feature under the pointer, the topmost of every layer
// registered on the map, and a tap for touch. `fn(properties)`
// gives {heading, text, color}; text lines split on \n
const HOVER = new WeakMap()
export function hover(map, layer, fn, { gl = globalThis.maplibregl,
  click = true } = {}) {
  let h = HOVER.get(map)
  if (!h) {
    const el = document.createElement('dd-label')
    h = { fns: {}, marker: new gl.Marker({ element: el, anchor: 'bottom-left',
      offset: [15, -7] }) }
    h.show = e => {
      const f = map.queryRenderedFeatures(e.point, { layers: Object.keys(h.fns)
        .filter(l => map.getLayer(l)) })[0]
      if (!f) return h.marker.remove()
      const { heading = '', text = '', color = '' } = h.fns[f.layer.id](
        f.properties) ?? {}
      el.setAttribute('heading', heading)
      el.setAttribute('color', color)
      el.innerHTML = String(text).split('\n').map(esc).join('<br>')
      // on the marking it names, up and right of it (pdf:73)
      h.marker.setLngLat(f.geometry.type === 'Point'
        ? f.geometry.coordinates : e.lngLat).addTo(map)
    }
    HOVER.set(map, h)
  }
  h.fns[layer] = fn
  map.on('mousemove', layer, e => {
    map.getCanvas().style.cursor = 'pointer'
    h.show(e)
  })
  if (click) map.on('click', layer, h.show)
  map.on('mouseleave', layer, () => {
    map.getCanvas().style.cursor = ''
    h.marker.remove()
  })
}

// a notebook's map in one call: the basemap, graded imagery, the markings,
// no chrome maplibre adds, a canvas print can read
export async function map(container, { gl = globalThis.maplibregl,
  imagery: sat = true, ...opts } = {}) {
  const m = new gl.Map({ container, style, attributionControl: false,
    canvasContextAttributes: { preserveDrawingBuffer: true }, ...opts })
  const ready = marks(m)
  await m.once('load')
  await ready
  if (sat) imagery(m, { gl, ...sat })
  return m
}
